INIT_SOURCE='"""Oracle scientific reasoning runtime subsystem."""\nfrom .oracle_scientific_reasoning_callable_registry import *\n'

def digest(p): return sha256(p.read_bytes()).hexdigest()
def write(p,s):
    p.parent.mkdir(parents=True,exist_ok=True); p.write_text(s.lstrip(),encoding="utf-8",newline="\n"); ast.parse(p.read_text(encoding="utf-8"),filename=str(p)); print(f"[OK] FULL REPLACEMENT: {p.resolve()}")
def main():
    print("========================================"); print(" OSR-001 INSTALLER"); print(" SCIENTIFIC REASONING CALLABLE REGISTRY"); print("========================================")
    if not OII015.is_file(): raise SystemExit("[ERROR] Actual OII-015 module missing")
    src=OII015.read_text(encoding="utf-8")
    for token in ('ENGINE_ID = "OII-015"','class IntegratedIntelligenceFinalCertification','def verify_integrated_intelligence_final_certification'):
        if token not in src: raise SystemExit("[ERROR] OII-015 contract mismatch")
    ast.parse(src,filename=str(OII015)); before=digest(OII015); print("[OK] Actual OII-015 terminal certification contract verified")
    write(PRODUCTION,PRODUCTION_SOURCE); write(TEST,TEST_SOURCE); write(INIT,INIT_SOURCE)
    if digest(OII015)!=before: raise RuntimeError("Protected OII-015 changed")
    print("[PASS] Protected OII-015 module unchanged")
    rc=subprocess.run([sys.executable,str(TEST)],cwd=str(ROOT),check=False).returncode
    if rc: raise SystemExit(rc)
    if digest(OII015)!=before: raise RuntimeError("Protected OII-015 changed after test")
    print("[PASS] Protected OII-015 module unchanged after test")
    print("[PASS] No analytics, Operator, or Q Series execution module modified")
    print("[DONE] OSR-001 SCIENTIFIC REASONING CALLABLE REGISTRY INSTALLED")
    return 0
